<?php require_once __DIR__.'/../functions.php'; init_db(); if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0) redirect('login.php'); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$u=trim($_POST['username']??'');$p=$_POST['password']??'';if(strlen($u)<3||strlen($p)<10)$err='Bitte Benutzername und ein Passwort mit mindestens 10 Zeichen eingeben.';else{$st=db()->prepare('INSERT INTO admins(username,password_hash,created_at) VALUES(?,?,CURRENT_TIMESTAMP)');$st->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);redirect('login.php');}} ?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Young Images – Einrichtung</title><link rel="stylesheet" href="../css/admin.css"></head><body><main class="login"><img src="../assets/young-images-logo.png" class="admin-logo"><h1>Redaktionssystem einrichten</h1><p>Lege einmalig deinen Admin-Zugang an.</p><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Benutzername<input name="username" required></label><label>Passwort<input type="password" name="password" minlength="10" required></label><button>Einrichtung abschließen</button></form></main></body></html>
